import os
import json
import uuid
from typing import List, Optional
from codx.junior.model.kanban import Kanban, KanbanColumn
from datetime import datetime


class KanbanManager:
    def __init__(self, base_path: str):
        self.base_path = base_path
        os.makedirs(self.base_path, exist_ok=True)


    def get_kanban_file(self, kanban: Kanban):
        return f"{self.base_path}/{kanban.doc_id}-{kanban.title}.json"


    def save_kanban(self, kanban: Kanban):
        if not kanban.doc_id:
            kanban.doc_id = str(uuid.uuid4())
        if not kanban.created_at:
            kanban.created_at = datetime.now().isoformat()
        kanban.updated_at = datetime.now().isoformat()
        
        file_path = self.get_kanban_file(kanban)
        os.makedirs(os.path.dirname(file_path), exist_ok=True)


        with open(file_path, 'w') as f:
            f.write(json.dumps(kanban.dict(), indent=2))


        return kanban


    def get_kanban(self, kanban_id: str) -> Optional[Kanban]:
        for filename in os.listdir(self.base_path):
            if kanban_id in filename:
                with open(os.path.join(self.base_path, filename), 'r') as f:
                    return Kanban(**json.load(f))
        return None


    def get_all_kanbans(self) -> List[Kanban]:
        kanbans = []
        for filename in os.listdir(self.base_path):
            if filename.endswith(".json"):
                with open(os.path.join(self.base_path, filename), 'r') as f:
                    kanbans.append(Kanban(**json.load(f)))
        return kanbans


    def delete_kanban(self, kanban_id: str):
        for filename in os.listdir(self.base_path):
            if kanban_id in filename:
                os.remove(os.path.join(self.base_path, filename))


    def get_kanban_tree(self):
        kanban_tree = {}
        kanbans = self.get_all_kanbans()
        for kanban in kanbans:
            current_level = kanban_tree
            if kanban.parent_id:
                parent_kanban = self.get_kanban(kanban.parent_id)
                if parent_kanban:
                    if parent_kanban.title not in current_level:
                        current_level[parent_kanban.title] = {}
                    current_level = current_level[parent_kanban.title]
            current_level[kanban.title] = {}
        return kanban_tree
